<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1><?= $deletionMode?'Delete Fee Invoices':'Fees Report' ?></h1><p><?= $deletionMode?'Review carefully before permanently deleting an invoice and its receipts.':'Live billed, paid and outstanding fee records.' ?></p></div><?php if(!$deletionMode):?><button class="btn btn--secondary" type="button" onclick="window.print()"><i data-lucide="printer"></i>Print</button><?php endif?></header>
<form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Search</label><input class="module-input" name="search" value="<?= e($search) ?>" placeholder="Student, registration or invoice"></div><div class="module-field"><label>Month</label><input class="module-input" type="month" name="month" value="<?= e($selectedMonth) ?>"></div><div class="module-field"><label>Status</label><select class="module-select" name="status"><option value="">All statuses</option><?php foreach(['unpaid','partial','paid','carried_forward']as$s):?><option value="<?= $s ?>" <?= $selectedStatus===$s?'selected':'' ?>><?= e(ucwords(str_replace('_',' ',$s))) ?></option><?php endforeach?></select></div><button class="btn btn--primary">Apply filters</button></form>
<div class="metric-grid"><div class="metric-card"><span>Total Billed</span><strong><?= number_format($totals['billed'],2) ?></strong></div><div class="metric-card"><span>Total Paid</span><strong><?= number_format($totals['paid'],2) ?></strong></div><div class="metric-card"><span>Outstanding</span><strong><?= number_format($totals['remaining'],2) ?></strong></div></div>
<section class="module-card"><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Invoice</th><th>Student</th><th>Month</th><th>Billed</th><th>Paid</th><th>Remaining</th><th>Status</th><?php if($deletionMode):?><th>Action</th><?php endif?></tr></thead><tbody><?php if(!$invoices):?><tr><td colspan="<?= $deletionMode?8:7 ?>"><div class="compact-empty"><h3>No fee invoices found</h3><p>Adjust the filters or generate an invoice from Collect Fees.</p></div></td></tr><?php else:foreach($invoices as$row):?><tr><td><?= e($row['invoice_no']) ?></td><td><strong><?= e($row['student_name']) ?></strong><br><small><?= e($row['registration_no'].' · '.$row['class_name']) ?></small></td><td><?= e($row['fee_month']) ?></td><td><?= number_format((float)$row['total_amount'],2) ?></td><td><?= number_format((float)$row['paid_amount'],2) ?></td><td><?= number_format((float)$row['remaining_amount'],2) ?></td><td><span class="student-status student-status--<?= $row['status']==='paid'?'active':'inactive' ?>"><?= e(ucwords(str_replace('_',' ',$row['status']))) ?></span></td><?php if($deletionMode):?><td><button class="class-action-button class-action-button--danger" type="button" data-fee-delete data-id="<?= $row['id'] ?>" data-invoice="<?= e($row['invoice_no']) ?>"><i data-lucide="trash-2"></i><span class="sr-only">Delete invoice</span></button></td><?php endif?></tr><?php endforeach;endif?></tbody></table></div></div></section></div></div></main>
<?php if($deletionMode):?><div class="modal-shell" id="feeDeleteModal" hidden aria-hidden="true" role="dialog" aria-modal="true"><button class="modal-shell__backdrop" type="button" data-fee-cancel></button><div class="modal-shell__dialog"><header class="modal-shell__header"><div><h2>Delete fee invoice?</h2><p id="feeDeleteMessage">This also permanently removes its payment receipts.</p></div></header><form id="feeDeleteForm" method="post"><?= csrf_field() ?><input type="hidden" name="confirm" value="delete"><div class="modal-shell__actions"><button class="btn btn--secondary" type="button" data-fee-cancel>Cancel</button><button class="btn btn--danger" type="submit">Delete invoice</button></div></form></div></div><script>document.addEventListener('click',function(e){var b=e.target.closest('[data-fee-delete]'),m=document.getElementById('feeDeleteModal');if(b){document.getElementById('feeDeleteMessage').textContent='Invoice '+b.dataset.invoice+' and all of its payment receipts will be permanently deleted.';document.getElementById('feeDeleteForm').action='<?= url('/admin/fees') ?>/'+b.dataset.id+'/delete';m.hidden=false;m.setAttribute('aria-hidden','false');document.body.classList.add('no-scroll')}if(e.target.closest('[data-fee-cancel]')){m.hidden=true;m.setAttribute('aria-hidden','true');document.body.classList.remove('no-scroll')}})</script><?php endif?>
